import {panel,matching,writeChapter} from './jee-tools.mjs';
// Class 8 sets every piece of maths in formula type ($…$), so no line mixes
// the two styles. In this source a TeX backslash is written twice ('\\times').
// Never write a digit/digit fraction: panel() turns it into \frac, and inside
// $…$ that breaks the formula. Write \\frac{a}{b} instead.
const tie=x=>typeof x==='string'?x.replace(/ ([×÷]) /g,' $1 '):Array.isArray(x)?x.map(tie):x;
// A matching panel carries "Each entry has exactly one match." in its opening
// sentence rather than on a line of its own: same words, one line shorter,
// which is what lets two matching panels share a page.
const p=(...a)=>panel(...a.map(tie)), m=(...a)=>matching(...a.map(tie))
  .replace('Match List I with List II.</p>','Match List I with List II. Each entry has exactly one match.</p>')
  .replace('<p>Each entry has exactly one match.</p>','');
const banks={};
const S='Single correct', M='Multiple correct', N='Numerical answer';

banks['ch01-square-and-cube']=[
p(1,S,'Which of these cannot be a perfect square?',['6724','3528','1296','7056'],['A perfect square never ends in 2, 3, 7 or 8, so 3528 is ruled out at once.','The others are squares: $82^2 = 6724$, $36^2 = 1296$ and $84^2 = 7056$.'],'(b) 3528'),
p(2,S,'What is $1 + 3 + 5 + \\cdots + 79$?',['1560','1640','3200','1600'],['$79 = 2 \\times 40 - 1$, so 79 is the 40th odd number.','The sum of the first 40 odd numbers is $40^2 = 1600$.'],'(d) 1600'),
p(3,S,'How many whole numbers lie strictly between $25^2$ and $26^2$?',['49','51','50','52'],['$26^2 - 25^2 = 2 \\times 25 + 1 = 51$.','The numbers strictly between are one fewer than this gap: $51 - 1 = 50$.'],'(c) 50'),
p(4,S,'By what smallest number must 3380 be divided so that the quotient is a perfect square?',['5','2','13','10'],['$3380 = 2^2 \\times 5 \\times 13^2$.','Only the 5 lacks a partner, so divide by 5: $3380 \\div 5 = 676 = 26^2$.'],'(a) 5'),
p(5,S,'238 328 is a perfect cube. What is its cube root?',['58','62','68','72'],['It ends in 8, and only $2^3$ ends in 8, so the root ends in 2.','238 lies between $6^3 = 216$ and $7^3 = 343$, so the tens digit is 6: the root is 62, and $62^3 = 238\\,328$.'],'(b) 62'),
p(6,S,'By what smallest number must 2560 be multiplied so that the product is a perfect cube?',['5','10','25','50'],['$2560 = 2^9 \\times 5$, and $2^9 = (2^3)^3$ is already a cube.','The single 5 needs two more: multiply by $5^2 = 25$, giving $64\\,000 = 40^3$.'],'(c) 25'),
p(7,M,'Which of these could be the last digit of a perfect square?',['2','4','7','9'],['The last digit of a square depends only on the last digit of the number: the squares of 0 to 9 end in 0, 1, 4, 9, 6, 5, 6, 9, 4, 1.','So 4 and 9 are possible; 2 and 7 never occur.'],'(b), (d)'),
p(8,M,'Which statements about 196 are correct?',['196 has an odd number of factors.','$\\sqrt{196} = 14$','$196 = 2^2 \\times 7^2$','196 is a perfect cube.'],['$196 = 14^2 = 2^2 \\times 7^2$. A perfect square has an odd number of factors, because its square root pairs with itself.','$5^3 = 125$ and $6^3 = 216$, so 196 is not a cube.'],'(a), (b), (c)'),
p(9,M,'Which statements are correct?',['$11^3 = 1221$','$11^3$ is the sum of the 11 consecutive odd numbers from 111 to 131.','$\\sqrt[3]{-1331} = -11$','$(-0.2)^3 = -0.08$'],['$11^3 = 1331$. The 11 odd numbers from 111 to 131 have average 121, so their sum is $11 \\times 121 = 1331$.','$(-11)^3 = -1331$, and $(-0.2)^3 = -0.008$, not $-0.08$.'],'(b), (c)'),
p(10,M,'In the corridor of 100 lockers, the lockers that end open are those with a perfect-square number. Which statements are correct?',['Locker 81 ends open.','Locker 72 ends open.','Exactly 10 lockers end open.','Locker 100 ends open.'],['A locker ends open when its number has an odd number of factors, which happens only for perfect squares.','The squares up to 100 are $1^2, 2^2, \\ldots, 10^2$: ten of them, including 81 and 100 but not 72.'],'(a), (c), (d)'),
p(11,N,'Find $\\sqrt{1764}$ by prime factorisation.',[],['$1764 = 2^2 \\times 3^2 \\times 7^2$.','$\\sqrt{1764} = 2 \\times 3 \\times 7 = 42$.'],'42'),
p(12,N,'Given that $60^2 = 3600$, find $61^2$ without multiplying.',[],['Going from $60^2$ to $61^2$ adds the 61st odd number, $2 \\times 61 - 1 = 121$.','$61^2 = 3600 + 121 = 3721$.'],'3721'),
p(13,N,'By what smallest number must 4375 be divided so that the quotient is a perfect cube?',[],['$4375 = 5^4 \\times 7$.','Three of the 5s make a cube; divide by the spare 5 and the 7: $4375 \\div 35 = 125 = 5^3$.'],'35'),
m(14,['$\\sqrt{2809}$','$\\sqrt[3]{3375}$','$15^2$','Whole numbers strictly between $15^2$ and $16^2$'],['30','225','53','15'],[3,4,2,1],['$53^2 = 2809$, $15^3 = 3375$, $15^2 = 225$, and $2 \\times 15 = 30$ numbers lie between $15^2$ and $16^2$.'],1),
m(15,['Last digit of $23^2$','Last digit of $23^3$','Last digit of $18^2$','Last digit of $18^3$'],['2','7','4','9'],[4,2,3,1],['Only last digits matter: $3^2 = 9$, $3^3 = 27$, $8^2 = 64$ and $8^3 = 512$ end in 9, 7, 4 and 2.'],2),
];

banks['ch02-power-play']=[
p(1,S,'What is $(-2)^4 - 2^4$?',['0','32','$-32$','16'],['An even power of a negative number is positive: $(-2)^4 = 16$.','$16 - 16 = 0$.'],'(a) 0'),
p(2,S,'If $(2^3)^n \\times 2^2 = 2^{14}$, what is $n$?',['3','4','5','6'],['$(2^3)^n \\times 2^2 = 2^{3n} \\times 2^2 = 2^{3n + 2}$.','$3n + 2 = 14$, so $n = 4$.'],'(b) 4'),
p(3,S,'$27^4 \\times 9^3$, written as a single power of 3, is',['$3^{36}$','$3^{24}$','$3^{18}$','$3^{12}$'],['$27^4 = (3^3)^4 = 3^{12}$ and $9^3 = (3^2)^3 = 3^6$.','$3^{12} \\times 3^6 = 3^{18}$.'],'(c) $3^{18}$'),
p(4,S,'What is $\\left(3^{-1} + 4^{-1}\\right)^{-1}$?',['$\\frac{7}{12}$','7','$\\frac{1}{7}$','$\\frac{12}{7}$'],['$3^{-1} + 4^{-1} = \\frac{1}{3} + \\frac{1}{4} = \\frac{7}{12}$.','The power $-1$ takes the reciprocal: $\\frac{12}{7}$.'],'(d) $\\frac{12}{7}$'),
p(5,S,'What is the last digit of $3^{25} + 7^{25}$?',['0','4','6','8'],['The last digits of the powers of 3 repeat 3, 9, 7, 1, and of 7 repeat 7, 9, 3, 1: every 4 powers.','$25 = 4 \\times 6 + 1$, so $3^{25}$ ends in 3 and $7^{25}$ in 7; $3 + 7 = 10$ ends in 0.'],'(a) 0'),
p(6,S,'A quiz has 6 questions, each with 3 options. In how many ways can the answer sheet be filled in, with one option per question?',['18','729','216','36'],['Each question can be answered in 3 ways, independently of the others.','$3 \\times 3 \\times 3 \\times 3 \\times 3 \\times 3 = 3^6 = 729$.'],'(b) 729'),
p(7,M,'Which of these are equal to $2^{12}$?',['$(2^3)^4$','$2^3 \\times 2^4$','$4^6$','$8^4$'],['$(2^3)^4 = 2^{12}$, $4^6 = (2^2)^6 = 2^{12}$ and $8^4 = (2^3)^4 = 2^{12}$.','$2^3 \\times 2^4 = 2^7$: exponents add when powers are multiplied.'],'(a), (c), (d)'),
p(8,M,'Which statements are true for every number $x \\ne 0$?',['$x^0 = 1$','$x^{-2} = \\frac{1}{x^2}$','$\\frac{(x^{-2})^3 \\times x^4}{x^{-5}} = x^3$','$x^2 \\times x^3 = x^6$'],['$x^0 = 1$ and $x^{-2} = \\frac{1}{x^2}$ by definition. In (c) the exponents give $-6 + 4 - (-5) = 3$.','$x^2 \\times x^3 = x^5$, not $x^6$.'],'(a), (b), (c)'),
p(9,M,'Which of these numbers are written in standard form?',['$3.25 \\times 10^9$','$32.5 \\times 10^8$','$5.2 \\times 10^{-8}$','$0.52 \\times 10^{-7}$'],['Standard form is a number from 1 up to (but not including) 10, times a power of 10.','32.5 is too large and 0.52 too small, although both numbers are correct in value.'],'(a), (c)'),
p(10,M,'Consider $3.2 \\times 10^{-3}$, $4.1 \\times 10^{-4}$, $2.9 \\times 10^{-3}$ and $1.5 \\times 10^{-2}$. Which statements are correct?',['The smallest is $4.1 \\times 10^{-4}$.','The largest is $1.5 \\times 10^{-2}$.','$3.2 \\times 10^{-3} < 2.9 \\times 10^{-3}$','$3.2 \\times 10^{-3} > 1.5 \\times 10^{-2}$'],['Compare the powers of 10 first: $10^{-4} < 10^{-3} < 10^{-2}$.','So $4.1 \\times 10^{-4}$ is smallest and $1.5 \\times 10^{-2}$ largest; with the same power, $2.9 < 3.2$.'],'(a), (b)'),
p(11,N,'Find the value of $\\frac{2^5 \\times 3^4 \\times 7}{6^3 \\times 14}$.',[],['$6^3 = 2^3 \\times 3^3$ and $14 = 2 \\times 7$, so the denominator is $2^4 \\times 3^3 \\times 7$.','Divide: $2^{5 - 4} \\times 3^{4 - 3} = 2 \\times 3 = 6$.'],'6'),
p(12,N,'Find $m$ if $5^m \\div 5^{-3} = 5^5$.',[],['$5^m \\div 5^{-3} = 5^{m - (-3)} = 5^{m + 3}$.','$m + 3 = 5$, so $m = 2$.'],'2'),
p(13,N,'A locker code is three letters, each from A to E, followed by two digits. How many codes are there?',[],['Each letter can be chosen in 5 ways and each digit in 10.','$5^3 \\times 10^2 = 125 \\times 100 = 12\\,500$.'],'12500'),
m(14,['$8^4 \\times 125^4$','$\\frac{15^4}{5^4 \\times 3^2}$','$\\frac{5^8 \\times 25^2}{125^3}$','$2^{10}$'],['125','1024','$10^{12}$','9'],[3,4,1,2],['$8^4 \\times 125^4 = 1000^4 = 10^{12}$, and $\\frac{15^4}{5^4} = 3^4$, so the second is $3^2 = 9$.','$\\frac{5^8 \\times 5^4}{5^9} = 5^3 = 125$, and $2^{10} = 1024$.'],0),
m(15,['$0.000\\,000\\,052$','$3\\,250\\,000\\,000$','The number of seconds in a week','$4.5 \\times 10^5 \\times 300$'],['$1.35 \\times 10^{8}$','$6.048 \\times 10^{5}$','$5.2 \\times 10^{-8}$','$3.25 \\times 10^{9}$'],[3,4,2,1],['Count the places the point moves. A week has $604\\,800$ s, and $4.5 \\times 10^5 \\times 300 = 1.35 \\times 10^8$.'],3),
];

banks['ch03-story-of-numbers']=[
p(1,S,'How is 1649 written in Roman numerals, using the subtractive rule wherever it shortens the numeral?',['MDCXLIX','MDCIL','MDCXLVIIII','MCDXLIX'],['$1649 = 1000 + 600 + 40 + 9$: M, DC, XL and IX.','So 1649 is MDCXLIX. IL is not allowed (I may stand only before V and X), and MCD is 1400.'],'(a) MDCXLIX'),
p(2,S,'What number is MMCDXCVI?',['2596','2496','2694','2406'],['MM is 2000, CD is $500 - 100 = 400$ and XC is $100 - 10 = 90$.','VI is 6, so the number is $2000 + 400 + 90 + 6 = 2496$.'],'(b) 2496'),
p(3,S,'A number system has the landmarks 1, 9, 81 and 729. What is its next landmark?',['810','1458','6561','5832'],['Each landmark is 9 times the one before, so the base is 9.','The next landmark is $729 \\times 9 = 6561$.'],'(c) 6561'),
p(4,S,'What number does the base-5 numeral $3042_{5}$ stand for?',['392','407','3042','397'],['With the places 125, 25, 5, 1: $3 \\times 125 + 0 \\times 25 + 4 \\times 5 + 2 = 397$.'],'(d) 397'),
p(5,S,'What number does the binary numeral $110101_{2}$ stand for?',['53','43','101','27'],['The places are 32, 16, 8, 4, 2, 1, so $110101_{2} = 32 + 16 + 4 + 1 = 53$.'],'(a) 53'),
p(6,S,'How is 100 written in base 3?',['$10102_{3}$','$10201_{3}$','$1021_{3}$','$11001_{3}$'],['With the landmarks 81, 27, 9, 3, 1: $100 = 1 \\times 81 + 0 \\times 27 + 2 \\times 9 + 0 \\times 3 + 1$.'],'(b) $10201_{3}$'),
p(7,M,'Which of these are correctly formed Roman numerals?',['XL','IC','XC','VX'],['XL is $50 - 10 = 40$ and XC is $100 - 10 = 90$: X may stand before L and C.','I may stand only before V and X, and V is never subtracted, so IC and VX are not allowed; 99 is XCIX and 5 is V.'],'(a), (c)'),
p(8,M,'A film runs for 10 000 seconds. Which statements are correct?',['It runs for 2 h 46 min 40 s.','It runs for 166 min 40 s.','It runs for more than 3 hours.','$10\\,000 = 2 \\times 60^2 + 46 \\times 60 + 40$'],['$10\\,000 \\div 60 = 166$ remainder 40, so 166 min 40 s; and $166 \\div 60 = 2$ remainder 46, so 2 h 46 min 40 s.','That is the base-sixty form in (d), and 3 hours would be $10\\,800$ seconds.'],'(a), (b), (d)'),
p(9,M,'The landmarks of base 4 are 1, 4, 16, 64, 256, … . Which statements are correct?',['256 is a landmark.','128 is a landmark.','$300 = 256 + 2 \\times 16 + 3 \\times 4$','In base 4, 300 is written $10230_{4}$.'],['The landmarks are powers of 4, and 128 is not one.','$256 + 32 + 12 = 300$ uses 1 of 256, 0 of 64, 2 of 16, 3 of 4 and 0 ones: the digits 1, 0, 2, 3, 0.'],'(a), (c), (d)'),
p(10,M,'The Egyptian symbols stand for 1, 10, 100, 1000, 10 000 and 100 000. Which statements about writing 40 506 are correct?',['It needs 4 of the symbol for 10 000.','It needs 5 of the symbol for 100.','It needs 15 symbols in all.','It needs 1 of the symbol for 10.'],['$40\\,506 = 4 \\times 10\\,000 + 5 \\times 100 + 6 \\times 1$.','That is $4 + 5 + 6 = 15$ symbols; the tens digit is 0, so no symbol for 10 is used.'],'(a), (b), (c)'),
p(11,N,'Using the Mayan landmarks 1, 20, 360 and 7200, $1000 = 2 \\times 360 + k \\times 20$. Find $k$.',[],['$1000 - 2 \\times 360 = 1000 - 720 = 280$.','$280 \\div 20 = 14$, with nothing left for the ones.'],'14'),
p(12,N,'In the Mesopotamian base-sixty system, $4000 = a \\times 3600 + b \\times 60 + c$, with $a$, $b$ and $c$ each less than 60. Find $b$.',[],['$4000 - 3600 = 400$, so $a = 1$.','$400 = 6 \\times 60 + 40$, so $b = 6$ and $c = 40$.'],'6'),
p(13,N,'Write $7 \\times 10^5 + 3 \\times 10^2 + 9$ as an ordinary numeral.',[],['The places run from $10^5$ down to $10^0$, and the empty ones get 0: the digits are 7, 0, 0, 3, 0, 9.'],'700309'),
m(14,['XLIX','XCIV','CDXL','MCM'],['1900','49','440','94'],[2,4,3,1],['XL + IX = 49, XC + IV = 94, CD + XL = 440 and M + CM = 1900.'],1),
m(15,['$1011_{2}$','$32_{4}$','$44_{5}$','$120_{3}$'],['15','24','11','14'],[3,4,2,1],['$8 + 2 + 1 = 11$, $3 \\times 4 + 2 = 14$, $4 \\times 5 + 4 = 24$ and $9 + 2 \\times 3 = 15$.'],2),
];

banks['ch04-quadrilaterals']=[
p(1,S,'A polygon has 44 diagonals. How many sides has it?',['9','10','11','12'],['A polygon with $n$ sides has $\\frac{n(n - 3)}{2}$ diagonals, so $n(n - 3) = 88$.','$11 \\times 8 = 88$, so $n = 11$.'],'(c) 11'),
p(2,S,'Five angles of a hexagon are each $112^\\circ$. What is the sixth angle?',['$160^\\circ$','$148^\\circ$','$120^\\circ$','$112^\\circ$'],['The angles of a hexagon add to $(6 - 2) \\times 180^\\circ = 720^\\circ$.','$720^\\circ - 5 \\times 112^\\circ = 720^\\circ - 560^\\circ = 160^\\circ$.'],'(a) $160^\\circ$'),
p(3,S,'Each interior angle of a regular polygon is $168^\\circ$. How many sides has it?',['24','30','28','36'],['Each exterior angle is $180^\\circ - 168^\\circ = 12^\\circ$.','The exterior angles add to $360^\\circ$, so there are $360 \\div 12 = 30$ sides.'],'(b) 30'),
p(4,S,'In parallelogram $ABCD$, $\\angle A = (3x + 10)^\\circ$ and $\\angle C = (5x - 30)^\\circ$. What is $\\angle B$?',['$70^\\circ$','$140^\\circ$','$20^\\circ$','$110^\\circ$'],['Opposite angles of a parallelogram are equal: $3x + 10 = 5x - 30$, so $x = 20$ and $\\angle A = 70^\\circ$.','Adjacent angles add to $180^\\circ$: $\\angle B = 180^\\circ - 70^\\circ = 110^\\circ$.'],'(d) $110^\\circ$'),
p(5,S,'Each interior angle of a regular polygon is 11 times each exterior angle. How many sides has it?',['24','22','12','11'],['Interior + exterior $= 180^\\circ$, and here that is 12 exterior angles, so each exterior angle is $15^\\circ$.','$360 \\div 15 = 24$ sides.'],'(a) 24'),
p(6,S,'The diagonals of rectangle $ABCD$ meet at $O$, and $\\angle AOB = 110^\\circ$. What is $\\angle OAB$?',['$55^\\circ$','$35^\\circ$','$70^\\circ$','$110^\\circ$'],['The diagonals of a rectangle are equal and bisect each other, so $OA = OB$.','Triangle $OAB$ is isosceles: $\\angle OAB = (180^\\circ - 110^\\circ) \\div 2 = 35^\\circ$.'],'(b) $35^\\circ$'),
p(7,M,'In quadrilateral $PQRS$, $PQ = QR = 5$ cm and $RS = SP = 8$ cm. Which statements are correct?',['$PQRS$ is a kite.','$PQRS$ must be a parallelogram.','Its diagonals are perpendicular.','It can be a rhombus.'],['Two pairs of equal adjacent sides make a kite, and the diagonals of a kite meet at right angles.','Its opposite sides are 5 cm and 8 cm, not equal, so it is neither a parallelogram nor a rhombus.'],'(a), (c)'),
p(8,M,'Which statements are true for every parallelogram?',['Its opposite sides are equal.','Its diagonals bisect each other.','Its diagonals are equal.','Its adjacent angles add to $180^\\circ$.'],['(a), (b) and (d) hold in every parallelogram.','Equal diagonals make it a rectangle; a parallelogram with angles $60^\\circ$ and $120^\\circ$ has unequal diagonals.'],'(a), (b), (d)'),
p(9,M,'In rhombus $ABCD$ the diagonals meet at $O$, and $\\angle ABC = 70^\\circ$. Which statements are correct?',['$\\angle AOB = 90^\\circ$','$\\angle ABO = 35^\\circ$','$\\angle BAC = 55^\\circ$','$\\angle BAD = 70^\\circ$'],['The diagonals of a rhombus meet at right angles and bisect its angles, so $\\angle ABO = 35^\\circ$.','$AB = BC$, so $\\angle BAC = (180^\\circ - 70^\\circ) \\div 2 = 55^\\circ$; and $\\angle BAD = 180^\\circ - 70^\\circ = 110^\\circ$.'],'(a), (b), (c)'),
p(10,M,'Which statements about polygons are correct?',['Their exterior angles add to $360^\\circ$.','Regular 7-gon: exterior angle $50^\\circ$.','Regular 9-gon: exterior angle $40^\\circ$.','An octagon\'s angles add to $1080^\\circ$.'],['Exterior angles make one full turn: $360 \\div 9 = 40$, but $360 \\div 7 \\approx 51.4$. An octagon has $6 \\times 180^\\circ = 1080^\\circ$.'],'(a), (c), (d)'),
p(11,N,'How many more diagonals has a 9-sided polygon than a 7-sided one?',[],['A 9-gon has $\\frac{9 \\times 6}{2} = 27$ diagonals and a heptagon $\\frac{7 \\times 4}{2} = 14$.','$27 - 14 = 13$.'],'13'),
p(12,N,'The angles of a pentagon are $x^\\circ$, $(x + 10)^\\circ$, $(x + 20)^\\circ$, $(x + 30)^\\circ$ and $(x + 40)^\\circ$. Find the largest angle, in degrees.',[],['The angles of a pentagon add to $540^\\circ$: $5x + 100 = 540$, so $x = 88$.','The largest is $88 + 40 = 128$.'],'128'),
p(13,N,'The perimeter of a parallelogram is 60 cm, and two adjacent sides are in the ratio $2 : 3$. Find the longer side, in cm.',[],['Two adjacent sides make half the perimeter: 30 cm, in $2 + 3 = 5$ parts.','One part is 6 cm, so the longer side is $3 \\times 6 = 18$ cm.'],'18'),
m(14,['Each angle of a regular hexagon','Each exterior angle of a regular octagon','The angle sum of a pentagon','The number of diagonals of a hexagon'],['9','$540^\\circ$','$120^\\circ$','$45^\\circ$'],[3,4,2,1],['$720^\\circ \\div 6 = 120^\\circ$ and $360^\\circ \\div 8 = 45^\\circ$.','$3 \\times 180^\\circ = 540^\\circ$, and a hexagon has $\\frac{6 \\times 3}{2} = 9$ diagonals.'],0),
m(15,['Diagonals that bisect each other','Diagonals that bisect each other and are equal','Diagonals that bisect each other at right angles','Diagonals that are equal and bisect each other at right angles'],['rhombus','square','parallelogram','rectangle'],[3,4,1,2],['Bisecting diagonals give a parallelogram; making them equal gives a rectangle.','Making them perpendicular gives a rhombus, and both together a square.'],2).replace('Match List I with List II.','Match each property of the diagonals of a quadrilateral with the quadrilateral it describes.'),
];

banks['p2ch01-percentages']=[
p(1,S,'At a concert, 369 seats are taken, and that is $45\\%$ of the seats in the hall. How many seats does the hall have?',['820','810','900','166'],['$45\\%$ of the seats is 369, so $1\\%$ is $369 \\div 45 = 8.2$ seats.','All the seats: $8.2 \\times 100 = 820$.'],'(a) 820'),
p(2,S,'After a cut of $15\\%$, a pressure cooker costs ₹595. What did it cost before the cut?',['₹684.25','₹700','₹680','₹610'],['After a $15\\%$ cut the price is $85\\%$ of the old price: $0.85 \\times P = 595$.','$P = 595 \\div 0.85 = 700$. Adding $15\\%$ of 595 back gives the wrong ₹684.25.'],'(b) ₹700'),
p(3,S,'A fare rises by $20\\%$ one year and by a further $5\\%$ the next. What single percentage rise has the same effect?',['$25\\%$','$24\\%$','$26\\%$','$30\\%$'],['The multipliers are $1.2$ and $1.05$, and one rise follows the other: $1.2 \\times 1.05 = 1.26$.','A multiplier of $1.26$ is a rise of $26\\%$, not $20\\% + 5\\%$.'],'(c) $26\\%$'),
p(4,S,'₹12 000 is deposited for 3 years at $5\\%$ a year, and each year\'s interest is added to the deposit. What is the amount at the end?',['₹13 800','₹13 230','₹12 600','₹13 891.50'],['Each year multiplies the deposit by $1.05$: $12\\,000 \\times 1.05^3$.','$1.05^3 = 1.157625$, so the amount is ₹13 891.50. Interest paid out each year would give only ₹13 800.'],'(d) ₹13 891.50'),
p(5,S,'Brass is made of copper and zinc in the ratio $13 : 7$. What percentage of brass is zinc?',['$35\\%$','$65\\%$','$53.8\\%$','$7\\%$'],['Brass is $13 + 7 = 20$ parts, of which 7 are zinc.','$\\frac{7}{20} = \\frac{35}{100} = 35\\%$.'],'(a) $35\\%$'),
p(6,S,'The rent of a shop in the market is $150\\%$ more than the rent of a shop at the edge of town. By what percentage is the edge-of-town rent less than the market rent?',['$150\\%$','$60\\%$','$40\\%$','$66\\tfrac{2}{3}\\%$'],['If the edge rent is 100, the market rent is $100 + 150 = 250$.','The edge rent is $150$ less than 250, and $\\frac{150}{250} = 60\\%$.'],'(b) $60\\%$'),
p(7,M,'Which of these are equal to $87.5\\%$?',['$\\frac{7}{8}$','$0.875$','$\\frac{875}{100}$','$\\frac{35}{40}$'],['$\\frac{7}{8} = 0.875 = 87.5\\%$, and $\\frac{35}{40} = \\frac{7}{8}$.','$\\frac{875}{100} = 8.75 = 875\\%$.'],'(a), (b), (d)'),
p(8,M,'A school had 640 students last year and has 544 this year. Which statements are correct?',['The number fell by 96.','The number fell by $15\\%$.','544 is $85\\%$ of 640.','A rise of $15\\%$ next year would bring it back to 640.'],['96 is $15\\%$ of 640, so 544 is $85\\%$ of it; but $15\\%$ of 544 is only 81.6, so (d) fails.'],'(a), (b), (c)'),
p(9,M,'A shopkeeper buys a mixer for ₹2400, marks it $25\\%$ above that, and then allows a discount of $10\\%$ on the marked price. Which statements are correct?',['The marked price is ₹3000.','The selling price is ₹2700.','The profit is $15\\%$.','The profit is $25\\%$.'],['Marked price $= 2400 \\times 1.25 = 3000$; selling price $= 3000 \\times 0.9 = 2700$.','Profit $= 300$ on a cost of 2400, which is $12.5\\%$.'],'(a), (b)'),
p(10,M,'In Village 1, 312 of the 480 homes have a tap; in Village 2, 406 of the 580 homes do. Which statements are correct?',['Village 1: $65\\%$ of homes have a tap.','Village 2 has the larger share.','Village 2 has more homes with a tap.','The shares differ by 10 points.'],['$\\frac{312}{480} = 65\\%$ and $\\frac{406}{580} = 70\\%$, only 5 points apart; and $406 > 312$.'],'(a), (b), (c)'),
p(11,N,'A syrup of 400 g is $12\\%$ sugar. How many grams of sugar must be stirred in to make it $20\\%$ sugar?',[],['It has $48$ g of sugar. Adding $s$ g gives $\\frac{48 + s}{400 + s} = \\frac{20}{100}$.','Multiply out: $5(48 + s) = 400 + s$, so $240 + 5s = 400 + s$, $4s = 160$ and $s = 40$.'],'40'),
p(12,N,'A scooter bought for ₹80 000 loses $20\\%$ of its value every year. What is it worth after 2 years, in rupees?',[],['Each year the value is multiplied by $0.8$.','$80\\,000 \\times 0.8 \\times 0.8 = 51\\,200$.'],'51200'),
p(13,N,'A trader wants to allow $10\\%$ off the marked price and still make a profit of $17\\%$. By what percentage above the cost price must the marked price be?',[],['Selling price $= 1.17 \\times$ cost, and it is also $0.9 \\times$ marked price.','Marked price $= \\frac{1.17}{0.9} \\times$ cost $= 1.3 \\times$ cost: $30\\%$ above.'],'30'),
m(14,['$64\\%$','$0.4\\%$','$2\\tfrac{1}{4}$','$0.045$'],['$4.5\\%$','$\\frac{16}{25}$','$225\\%$','$\\frac{1}{250}$'],[2,4,3,1],['$\\frac{64}{100} = \\frac{16}{25}$, $\\frac{0.4}{100} = \\frac{1}{250}$, $2\\tfrac{1}{4} = 225\\%$ and $0.045 = 4.5\\%$.'],0),
m(15,['A rise of $20\\%$','A fall of $20\\%$','A rise of $20\\%$, then a fall of $20\\%$','A rise of $25\\%$, then a fall of $20\\%$'],['1','0.96','1.2','0.8'],[3,4,2,1],['A rise of $20\\%$ multiplies by $1.2$ and a fall by $0.8$; in turn, $1.2 \\times 0.8 = 0.96$ and $1.25 \\times 0.8 = 1$.'],2).replace('Match List I with List II.','Match each change with the single multiplier that has the same effect.'),
];

banks['p2ch02-baudhayana']=[
p(1,S,'A right-angled triangle has short sides 20 cm and 48 cm. What is its hypotenuse?',['52 cm','68 cm','56 cm','44 cm'],['$20^2 + 48^2 = 400 + 2304 = 2704$.','$\\sqrt{2704} = 52$.'],'(a) 52 cm'),
p(2,S,'A right-angled triangle has hypotenuse 65 and one short side 16. What is the other short side?',['49','63','61','81'],['$65^2 - 16^2 = (65 - 16)(65 + 16) = 49 \\times 81$.','$\\sqrt{49 \\times 81} = 7 \\times 9 = 63$.'],'(b) 63'),
p(3,S,'A ladder 8.9 m long leans against a wall with its foot 3.9 m from the wall. How high up the wall does it reach?',['5 m','7.5 m','8 m','9.8 m'],['$8.9^2 - 3.9^2 = (8.9 - 3.9)(8.9 + 3.9) = 5 \\times 12.8 = 64$.','The height is $\\sqrt{64} = 8$ m.'],'(c) 8 m'),
p(4,S,'The diagonals of a rhombus are 18 cm and 80 cm. What is the length of a side?',['49 cm','45 cm','40 cm','41 cm'],['The diagonals of a rhombus bisect each other at right angles, making right triangles with short sides 9 cm and 40 cm.','$9^2 + 40^2 = 81 + 1600 = 1681 = 41^2$.'],'(d) 41 cm'),
p(5,S,'Which set of sides makes a right-angled triangle?',['33, 56, 65','6, 7, 9','5, 11, 13','8, 14, 17'],['$33^2 + 56^2 = 1089 + 3136 = 4225 = 65^2$.','$36 + 49 = 85 \\ne 81$, $25 + 121 = 146 \\ne 169$ and $64 + 196 = 260 \\ne 289$.'],'(a) 33, 56, 65'),
p(6,S,'A square has an area of $18 \\text{ cm}^2$. What is the side of the square built on its diagonal?',['$3\\sqrt{2}$ cm','6 cm','9 cm','36 cm'],['The square on the diagonal has twice the area: $36 \\text{ cm}^2$.','Its side is $\\sqrt{36} = 6$ cm.'],'(b) 6 cm'),
p(7,M,'Which of these are Baudhāyana triples?',['$(27, 36, 45)$','$(12, 35, 37)$','$(6, 7, 9)$','$(13, 84, 85)$'],['$27^2 + 36^2 = 2025 = 45^2$, $12^2 + 35^2 = 1369 = 37^2$ and $13^2 + 84^2 = 7225 = 85^2$.','$6^2 + 7^2 = 85$, but $9^2 = 81$.'],'(a), (b), (d)'),
p(8,M,'The triple machine uses $m^2 - n^2$, $2mn$ and $m^2 + n^2$. With $m = 8$ and $n = 3$, which statements are correct?',['$m^2 - n^2 = 55$','$2mn = 24$','$m^2 + n^2 = 73$','$55^2 + 48^2 = 73^2$'],['$64 - 9 = 55$, $2 \\times 8 \\times 3 = 48$ and $64 + 9 = 73$.','$3025 + 2304 = 5329 = 73^2$. $2mn$ is 48, not 24.'],'(a), (c), (d)'),
p(9,M,'A box is 2 cm by 3 cm by 6 cm. Which statements are correct?',['The diagonal of its 2 cm by 6 cm face is $\\sqrt{40}$ cm.','The longest straight rod that fits inside is 7 cm.','The longest straight rod that fits inside is 11 cm.','The diagonal of its 2 cm by 3 cm face is 5 cm.'],['$2^2 + 6^2 = 40$, and corner to corner $\\sqrt{4 + 9 + 36} = 7$ cm; but $\\sqrt{4 + 9} = \\sqrt{13}$, not 5.'],'(a), (b)'),
p(10,M,'A carpenter makes a frame 60 cm by 80 cm and measures its diagonal as 99 cm. Which statements are correct?',['A frame with right-angled corners would have a diagonal of 100 cm.','The frame is not a true rectangle.','Every corner of the frame is exactly $90^\\circ$.','The diagonal is 1 cm shorter than it should be.'],['$60^2 + 80^2 = 3600 + 6400 = 10\\,000 = 100^2$.','A diagonal of 99 cm means the corners are not right angles; it is 1 cm short.'],'(a), (b), (d)'),
p(11,N,'A rectangle is 7 cm wide, and its diagonal is 1 cm longer than its length. Find its length, in cm.',[],['With length $l$: $(l + 1)^2 = l^2 + 7^2$.','$2l + 1 = 49$, so $l = 24$ cm, and the diagonal is 25 cm.'],'24'),
p(12,N,'A rectangular panel is 1.2 m wide and 0.5 m high. How long is a bar fixed along its diagonal, in metres?',[],['$1.2^2 + 0.5^2 = 1.44 + 0.25 = 1.69$.','$\\sqrt{1.69} = 1.3$ m.'],'1.3'),
p(13,N,'A multiple of the triple $(12, 35, 37)$ has largest number 111. What is its smallest number?',[],['$111 = 3 \\times 37$, so the multiple is 3 times the triple.','$3 \\times 12 = 36$; the triple is $(36, 105, 111)$.'],'36'),
m(14,['Short sides 5 and 12','Short sides 8 and 15','Short sides 7 and 24','Short sides 20 and 21'],['25','29','13','17'],[3,4,1,2],['$25 + 144 = 13^2$, $64 + 225 = 17^2$, $49 + 576 = 25^2$ and $400 + 441 = 29^2$.'],3).replace('Match List I with List II.','Match the short sides of each right-angled triangle with its hypotenuse.'),
m(15,['$\\sqrt{2}$','$\\sqrt{3}$','$\\sqrt{5}$','$\\sqrt{8}$'],['1.73 and 1.74','2.82 and 2.83','2.23 and 2.24','1.41 and 1.42'],[4,1,3,2],['Square the ends: $1.41^2 \\lt 2 \\lt 1.42^2$, $1.73^2 \\lt 3 \\lt 1.74^2$, $2.23^2 \\lt 5 \\lt 2.24^2$, $2.82^2 \\lt 8 \\lt 2.83^2$.'],1).replace('Match List I with List II.','Match each square root with the two numbers, to two decimal places, between which it lies.'),
];

banks['p2ch03-proportion']=[
p(1,S,'If $7 : x :: 21 : 36$, what is $x$?',['12','108','15','9'],['In a proportion the product of the extremes equals the product of the means: $7 \\times 36 = 21 \\times x$.','$252 = 21x$, so $x = 12$.'],'(a) 12'),
p(2,S,'Nine notebooks cost ₹315. What do fourteen cost?',['₹450','₹490','₹520','₹441'],['One notebook costs $315 \\div 9 = 35$ rupees.','Fourteen cost $14 \\times 35 = 490$ rupees.'],'(b) ₹490'),
p(3,S,'₹3000 is divided among three friends in the ratio $3 : 5 : 7$. What is the largest share?',['₹1000','₹1200','₹1400','₹1500'],['There are $3 + 5 + 7 = 15$ parts, so one part is $3000 \\div 15 = 200$ rupees.','The largest share is $7 \\times 200 = 1400$ rupees.'],'(c) ₹1400'),
p(4,S,'A map is drawn at $1 : 30\\,00\\,000$. Two towns are 7.5 cm apart on it. How far apart are they on the ground?',['22.5 km','2250 km','30 km','225 km'],['1 cm on the map is $30\\,00\\,000$ cm $= 30$ km on the ground.','$7.5 \\times 30 = 225$ km.'],'(d) 225 km'),
p(5,S,'A bus at 40 km/h takes 6 hours over a journey. How long does it take at 48 km/h?',['5 hours','7.2 hours','4.8 hours','6 hours'],['The distance is fixed, $40 \\times 6 = 240$ km, so speed and time are in inverse proportion.','$240 \\div 48 = 5$ hours.'],'(a) 5 hours'),
p(6,S,'Asha can paint a wall in 10 hours and Bina in 15 hours. How long do they take working together?',['12.5 hours','6 hours','25 hours','5 hours'],['In one hour Asha paints $\\frac{1}{10}$ of the wall and Bina $\\frac{1}{15}$: together $\\frac{3}{30} + \\frac{2}{30} = \\frac{1}{6}$.','So the whole wall takes 6 hours.'],'(b) 6 hours'),
p(7,M,'Which ratios are proportional to $6 : 15$?',['$14 : 35$','$2 : 5$','$12 : 25$','$18 : 45$'],['$6 : 15 = 2 : 5$, and $14 : 35$ and $18 : 45$ also reduce to $2 : 5$.','$12 : 25$ does not: $12 \\times 5 = 60$ but $25 \\times 2 = 50$.'],'(a), (b), (d)'),
p(8,M,'Which pairs of quantities are in inverse proportion?',['Speed and time, for a fixed distance','Number of workers and days to finish a fixed job','Number of notebooks and their total cost','Distance on a map and distance on the ground'],['In (a) and (b) the product stays fixed: doubling one halves the other.','In (c) and (d) the ratio stays fixed, so they are in direct proportion.'],'(a), (b)'),
p(9,M,'In a pie chart of the 1250 students of a school, the slice for students who cycle is $72^\\circ$. Which statements are correct?',['250 students cycle.','$20\\%$ of the students cycle.','500 students would get $144^\\circ$.','$90^\\circ$ stands for 300 students.'],['$\\frac{72}{360} = 20\\%$, and $20\\%$ of 1250 is 250; twice as many is $144^\\circ$. But $\\frac{90}{360} \\times 1250 = 312.5$.'],'(a), (b), (c)'),
p(10,M,'A rectangle has a perimeter of 84 cm, and its length and breadth are in the ratio $4 : 3$. Which statements are correct?',['Its length is 24 cm.','Its breadth is 18 cm.','Its area is $432 \\text{ cm}^2$.','Its diagonal is 30 cm.'],['Length + breadth $= 42$ cm in 7 parts of 6 cm: 24 cm and 18 cm, and $24 \\times 18 = 432$.','$24^2 + 18^2 = 576 + 324 = 900 = 30^2$.'],'(a), (b), (c), (d)'),
p(11,N,'A pipe fills a tank in 4 hours, and a drain empties the full tank in 6 hours. Both are left open. How many hours does the empty tank take to fill?',[],['In one hour the tank gains $\\frac{1}{4} - \\frac{1}{6} = \\frac{3}{12} - \\frac{2}{12} = \\frac{1}{12}$ of itself.','So it fills in 12 hours.'],'12'),
p(12,N,'A printer prints 1350 pages in 25 minutes. How many pages does it print in 40 minutes at the same rate?',[],['It prints $1350 \\div 25 = 54$ pages a minute.','In 40 minutes: $54 \\times 40 = 2160$ pages.'],'2160'),
p(13,N,'A fruit drink is mixed mango, orange and pineapple in the ratio $4 : 3 : 1$. There is 1.2 litres of orange. How many litres of drink are there in all?',[],['3 parts are 1.2 litres, so 1 part is 0.4 litres.','The drink is $4 + 3 + 1 = 8$ parts: $8 \\times 0.4 = 3.2$ litres.'],'3.2'),
m(14,['A 20 m wall, drawn on the plan','A 1 cm line on the plan, on the ground','A 4 cm line on the plan, on the ground','A 12 cm line on the plan, on the ground'],['30 m','8 cm','2.5 m','10 m'],[2,3,4,1],['1 cm on the plan is 2.5 m on the ground: 20 m is 8 cm, and 4 cm and 12 cm are 10 m and 30 m.'],2).replace('Match List I with List II.','A plan is drawn at a scale of $1 : 250$. Match List I with List II.'),
m(15,['Bus, 480 people','Train, 300 people','Car, 240 people','Walk, 180 people'],['$72^\\circ$','$54^\\circ$','$144^\\circ$','$90^\\circ$'],[3,4,1,2],['Each person is $\\frac{360}{1200} = 0.3$ degrees, so 480, 300, 240 and 180 people take $144^\\circ$, $90^\\circ$, $72^\\circ$, $54^\\circ$.'],0).replace('Match List I with List II.','A pie chart shows how 1200 people travel. Match each group with its angle.'),
];

banks['p2ch04-shapes']=[
p(1,S,'A Sierpiński carpet is begun from a square of side 54 cm. At step 2, what is the side of each remaining square?',['6 cm','18 cm','2 cm','27 cm'],['At each step every square is cut into 9 squares with a third of its side, and the middle one is removed.','After two steps the side is $54 \\div 3 \\div 3 = 6$ cm.'],'(a) 6 cm'),
p(2,S,'At each step of a Sierpiński triangle, every triangle becomes 3 smaller ones. A Sierpiński triangle has 2187 triangles. Which step is it at?',['6','7','8','729'],['The counts are $1, 3, 9, 27, \\ldots$: step $n$ has $3^n$ triangles.','$2187 = 3^7$, so it is step 7.'],'(b) 7'),
p(3,S,'A pyramid has 10 vertices. How many edges has it?',['10','20','18','9'],['A pyramid has one apex, so its base has $10 - 1 = 9$ corners: it is a nonagonal pyramid.','It has 9 base edges and 9 slant edges: $9 + 9 = 18$.'],'(c) 18'),
p(4,S,'A solid of the kind in this chapter has 20 faces and 30 edges. How many vertices has it?',['10','50','8','12'],['For these solids $F + V - E = 2$.','$20 + V - 30 = 2$, so $V = 12$.'],'(d) 12'),
p(5,S,'The net of a cube has an area of $150 \\text{ cm}^2$. What is the volume of the cube?',['$125 \\text{ cm}^3$','$25 \\text{ cm}^3$','$150 \\text{ cm}^3$','$216 \\text{ cm}^3$'],['The net is 6 equal squares, each $150 \\div 6 = 25 \\text{ cm}^2$, so the edge is 5 cm.','Volume $= 5^3 = 125 \\text{ cm}^3$.'],'(a) $125 \\text{ cm}^3$'),
p(6,S,'A prism and a pyramid are built on the same polygon. Between them they have 40 edges. What is the polygon?',['a hexagon','an octagon','a pentagon','a decagon'],['On an $n$-sided polygon a prism has $3n$ edges and a pyramid $2n$.','$5n = 40$, so $n = 8$: an octagon.'],'(b) an octagon'),
p(7,M,'A net is made of one regular pentagon with an identical triangle on each of its five sides. Which statements about the solid it folds into are correct?',['It is a pentagonal pyramid.','It has 6 faces.','It has 10 edges.','It has 5 vertices.'],['The triangles meet at one apex over the pentagon: a pentagonal pyramid, with $1 + 5 = 6$ faces.','It has 5 base edges and 5 slant edges, and $5 + 1 = 6$ vertices. Check: $6 + 6 - 10 = 2$.'],'(a), (b), (c)'),
p(8,M,'Which statements about a hexagonal prism are correct?',['It has 12 vertices.','It has 18 edges.','It has 6 faces.','$F + V - E = 2$ for it.'],['Two hexagons give $6 + 6 = 12$ vertices, and $6 + 6 + 6 = 18$ edges.','It has 2 hexagons and 6 rectangles, 8 faces: $8 + 12 - 18 = 2$.'],'(a), (b), (d)'),
p(9,M,'A solid has a square for its top view and a triangle for both its front and its side view. Which statements are correct?',['It can be a square pyramid.','It can be a cube.','If it is a square pyramid, it has 5 faces.','It can be a cone.'],['A square pyramid seen from above shows its square base, and from the front and side shows triangles; it has $1 + 4 = 5$ faces.','A cube shows squares from the front, and a cone shows a circle from above.'],'(a), (c)'),
p(10,M,'A box with no lid is 10 cm long, 6 cm wide and 4 cm high. Which statements are correct?',['Its net uses $188 \\text{ cm}^2$ of card.','With a lid, the net would use $228 \\text{ cm}^2$.','Its volume is $240 \\text{ cm}^3$.','Its net has 5 rectangles.'],['Base $60$, two long sides $2 \\times 40 = 80$ and two short sides $2 \\times 24 = 48$: $188 \\text{ cm}^2$, in 5 rectangles.','A lid adds another 60, giving $248 \\text{ cm}^2$; the volume is $10 \\times 6 \\times 4 = 240 \\text{ cm}^3$.'],'(a), (c), (d)'),
p(11,N,'A box is 12 cm long, 5 cm wide and 4 cm high. An ant walks on its surface from one corner to the opposite corner. Find the length of the shortest route, in cm.',[],['Unfold two faces into one rectangle; the three ways give $\\sqrt{12^2 + 9^2} = 15$, $\\sqrt{17^2 + 4^2} = \\sqrt{305}$ and $\\sqrt{16^2 + 5^2} = \\sqrt{281}$.','$15^2 = 225$ is the smallest of 225, 305 and 281, so the shortest route is 15 cm.'],'15'),
p(12,N,'At each step of a Sierpiński triangle, every triangle becomes 3 smaller ones. How many triangles are there at step 4?',[],['Step $n$ has $3^n$ triangles.','$3^4 = 81$.'],'81'),
p(13,N,'A Sierpiński carpet is begun from a square of side 81 cm. What area, in $\\text{cm}^2$, is left at step 2?',[],['Each step keeps $\\frac{8}{9}$ of the area, since 8 of the 9 small squares stay.','$81^2 \\times \\frac{8}{9} \\times \\frac{8}{9} = 6561 \\times \\frac{64}{81} = 5184$.'],'5184'),
m(14,['Triangular prism','Square pyramid','Cube','Tetrahedron'],['12','6','9','8'],[3,4,1,2],['A triangular prism has $3 + 3 + 3 = 9$ edges and a square pyramid $4 + 4 = 8$.','A cube has 12 edges and a tetrahedron 6.'],2).replace('Match List I with List II.','Match each solid in List I with its number of edges in List II.'),
m(15,['Six squares','Two triangles and three rectangles','One square and four triangles','Four triangles'],['triangular prism','cube','triangular pyramid','square pyramid'],[2,1,4,3],['Six squares fold into a cube, and two triangles with three rectangles into a triangular prism.','A square with four triangles makes a square pyramid, and four triangles a triangular pyramid.'],1).replace('Match List I with List II.','Match each net in List I with the solid it folds into.'),
];

banks['p2ch05-data']=[
p(1,S,'Nine values have a mean of 40. A tenth value, 60, is included. What is the new mean?',['42','50','41','44'],['The nine values add to $9 \\times 40 = 360$; with 60 the total is 420.','$420 \\div 10 = 42$.'],'(a) 42'),
p(2,S,'Ten values have a mean of 25. Two of them, 19 and 35, are removed. What is the mean of the rest?',['25','24.5','26','23'],['The ten add to 250; removing $19 + 35 = 54$ leaves 196.','$196 \\div 8 = 24.5$.'],'(b) 24.5'),
p(3,S,'Marks out of 20 have mean 13.5. What is their mean as marks out of 100?',['13.5','33.5','67.5','70'],['Every mark, and so the mean, is multiplied by 5: $13.5 \\times 5 = 67.5$.'],'(c) 67.5'),
p(4,S,'What is the median of 14, 9, 21, 9, 17, 30, 12 and 25?',['14','17','16','15.5'],['In order: 9, 9, 12, 14, 17, 21, 25, 30. With 8 values the median is halfway between the 4th and 5th.','$\\frac{14 + 17}{2} = 15.5$.'],'(d) 15.5'),
p(5,S,'The mean of six numbers is 18. Five of them are 12, 15, 20, 22 and 25. What is the sixth?',['14','18','16','12'],['The six add to $6 \\times 18 = 108$, and the five given add to 94.','The sixth is $108 - 94 = 14$.'],'(a) 14'),
p(6,S,'The mean of 20 observations was found to be 45. Later it was noticed that 64 had been read as 46. What is the correct mean?',['44.1','45.9','46.8','45'],['The total was $20 \\times 45 = 900$, but it should be $64 - 46 = 18$ more: 918.','$918 \\div 20 = 45.9$.'],'(b) 45.9'),
p(7,M,'Consider the values 9, 12, 13, 15 and 21. Which statements are correct?',['Their differences from 14 add to 0.','Their mean is 14.','Their median is 13.','Their mean is 15.'],['The differences from 14 are $-5, -2, -1, +1, +7$, which add to 0, so 14 is the balance point, the mean.','The middle of the five values in order is 13.'],'(a), (b), (c)'),
p(8,M,'5 is added to every value in a set of data. Which statements are correct?',['The mean goes up by 5.','The median goes up by 5.','The difference between the highest and lowest value goes up by 5.','The mean doubles.'],['Every value, and so the middle value and the balance point, moves up by 5.','The highest and lowest both move up by 5, so their difference is unchanged; nothing doubles.'],'(a), (b)'),
p(9,M,'In a frequency table the values 1, 2 and 3 occur 4, $f$ and 6 times, and the mean is 2.1. Which statements are correct?',['$f = 10$','There are 20 observations.','The median is 2.','The most common value is 3.'],['$\\frac{4 + 2f + 18}{10 + f} = 2.1$ gives $f = 10$: 20 values, whose 10th and 11th, and most common, are all 2.'],'(a), (b), (c)'),
p(10,M,'Shop A sold 210 school bags and Shop B sold 240. A poster shows both as bars on an axis that starts at 200. Which statements are correct?',['Shop B sold 30 more bags.','Shop B sold $30\\%$ more bags.','Shop B\'s bar looks 4 times as tall as Shop A\'s.','Shop B sold 4 times as many bags.'],['$240 - 210 = 30$ more, which is $\\frac{30}{210}$, about $14\\%$, not $30\\%$.','Above 200 the bars are 10 and 40 tall, so B\'s looks 4 times as tall; a cut axis exaggerates the difference.'],'(a), (c)'),
p(11,N,'The value 40 is included with 14, 9, 21, 9, 17, 30, 12 and 25. What is the median now?',[],['In order: 9, 9, 12, 14, 17, 21, 25, 30, 40.','With 9 values the median is the 5th: 17.'],'17'),
p(12,N,'The mean of 4, 6, 8 and $x$ is 7. Find $x$.',[],['The four values add to $4 \\times 7 = 28$.','$x = 28 - 4 - 6 - 8 = 10$.'],'10'),
p(13,N,'One section of 25 students has a mean mark of 40, and another of 15 students has a mean mark of 48. Find the mean mark of all 40 students.',[],['Total $= 25 \\times 40 + 15 \\times 48 = 1000 + 720 = 1720$.','$1720 \\div 40 = 43$.'],'43'),
m(14,['The mean of 2, 3, 3, 5, 7, 10','The median of 2, 3, 3, 5, 7, 10','The difference between the highest and lowest of 2, 3, 3, 5, 7, 10','The sum of 2, 3, 3, 5, 7, 10'],['8','30','5','4'],[3,4,1,2],['The sum is 30, the mean $30 \\div 6 = 5$, the median $\\frac{3 + 5}{2} = 4$, and $10 - 2 = 8$.'],3),
m(15,['5 is added to every value','Every value is multiplied by 3','Every value is doubled and then 4 is added','8 is taken from every value'],['12','44','25','60'],[3,4,2,1],['The mean changes as each value does: $20 + 5 = 25$, $20 \\times 3 = 60$, $20 \\times 2 + 4 = 44$, $20 - 8 = 12$.'],0).replace('Match List I with List II.','A set of data has mean 20. Match each change in List I with the new mean in List II.'),
];

banks['p2ch06-algebra-play']=[
p(1,S,'Think of a number, multiply it by 3, add 12, divide by 3, and subtract the number you thought of. What is the result?',['4','12','3','It depends on the number.'],['With the number $n$: $\\frac{3n + 12}{3} - n = n + 4 - n$.','The result is always 4.'],'(a) 4'),
p(2,S,'A trick runs: think of a number, multiply by 4, add $k$, divide by 2, and subtract twice the number. What must $k$ be for the answer always to be 7?',['7','14','28','3.5'],['$\\frac{4n + k}{2} - 2n = 2n + \\frac{k}{2} - 2n = \\frac{k}{2}$.','$\\frac{k}{2} = 7$, so $k = 14$.'],'(b) 14'),
p(3,S,'A date trick: multiply the month by 4, add 3, multiply by 25, and add the day. What must be taken from the result to show the month followed by the two digits of the day?',['25','3','75','100'],['$(4m + 3) \\times 25 + d = 100m + 75 + d$.','Taking away 75 leaves $100m + d$, the month followed by the day.'],'(c) 75'),
p(4,S,'The nine dates of a $3 \\times 3$ square on a calendar add to 153. What is the smallest date in the square?',['17','13','1','9'],['The nine dates are the centre $c$ and pairs around it that add to $2c$, so their sum is $9c = 153$, and $c = 17$.','The smallest, top left, is $c - 8 = 9$.'],'(d) 9'),
p(5,S,'The digits of a two-digit number add to 12. Reversing the digits gives a number 18 less. What is the number?',['75','57','84','66'],['With digits $a$ and $b$: $(10a + b) - (10b + a) = 9(a - b) = 18$, so $a - b = 2$.','$a + b = 12$ and $a - b = 2$ give $a = 7$ and $b = 5$: the number is 75.'],'(a) 75'),
p(6,S,'In a pyramid of numbers each box is the sum of the two below it. The bottom row of a four-row pyramid is 2, 4, 6, 8. What is at the top?',['20','40','80','36'],['With bottom row $a, b, c, d$, the top is $a + 3b + 3c + d$.','$2 + 12 + 18 + 8 = 40$.'],'(b) 40'),
p(7,M,'A six-digit number is made by writing a three-digit number twice, such as 385 385. By which of these is every such number divisible?',['7','11','13','17'],['Writing $abc$ twice gives $abc \\times 1000 + abc = abc \\times 1001$.','$1001 = 7 \\times 11 \\times 13$, and 17 is not a factor: $385\\,385 \\div 17$ is not whole.'],'(a), (b), (c)'),
p(8,M,'A three-digit number and the two numbers made by cycling its digits add to 2220. Which statements are correct?',['The sum is a multiple of 111.','The digits add to 20.','The digits add to 22.','The number could have the digits 9, 9 and 2.'],['$\\overline{abc} + \\overline{bca} + \\overline{cab} = 111(a + b + c)$.','$2220 \\div 111 = 20$, and $9 + 9 + 2 = 20$.'],'(a), (b), (d)'),
p(9,M,'A $2 \\times 2$ square of dates on a calendar adds to 104. Which statements are correct?',['The smallest date is 22.','The largest date is 30.','The sum is always 4 times the smallest date, plus 16.','A $2 \\times 2$ square could add to 105.'],['The dates are $a$, $a + 1$, $a + 7$, $a + 8$, adding to $4a + 16 = 104$: $a = 22$ and the largest is 30.','$4a + 16$ is always even, so 105 is impossible.'],'(a), (b), (c)'),
p(10,M,'A cycle shop has 20 bicycles and tricycles, with 48 wheels between them. Which statements are correct?',['There are 12 bicycles.','There are 8 tricycles.','If all 20 were bicycles there would be 40 wheels.','If all 20 were tricycles there would be 60 wheels.'],['All bicycles would give 40 wheels; each tricycle adds 1 more, so there are $48 - 40 = 8$ tricycles and 12 bicycles.','Check: $12 \\times 2 + 8 \\times 3 = 48$; all tricycles would give 60.'],'(a), (b), (c), (d)'),
p(11,N,'Veena thinks of a number, multiplies it by 3, subtracts 5 and doubles the result. She gets 38. What number did she think of?',[],['Undo the steps in reverse: $38 \\div 2 = 19$ and $19 + 5 = 24$.','$24 \\div 3 = 8$.'],'8'),
p(12,N,'A genie doubles a traveller\'s coins at each round and then takes 10. After two rounds the traveller has 30 coins. How many did the traveller start with?',[],['Before the second round: $(30 + 10) \\div 2 = 20$.','Before the first: $(20 + 10) \\div 2 = 15$.'],'15'),
p(13,N,'The digits 2, 7 and 8 are placed in $\\square\\,\\square \\times \\square$, one in each box. What is the largest product?',[],['The largest digit should multiply: try $72 \\times 8 = 576$ and $82 \\times 7 = 574$.','The other arrangements give at most $87 \\times 2 = 174$, so the largest is 576.'],'576'),
m(14,['$x$','The left box of the middle row','The right box of the middle row','The top'],['25','40','5','15'],[3,4,1,2],['The middle row is $x + 2x = 3x$ and $2x + 3x = 5x$, and the top is $8x = 40$, so $x = 5$.','So the middle row is 15 and 25.'],2).replace('Match List I with List II.','In a three-row pyramid each box is the sum of the two below it. The bottom row is $x$, $2x$, $3x$ and the top is 40. Match List I with List II.'),
m(15,['Multiply by 2, add 10, divide by 2, subtract the number','Multiply by 3, add 12, divide by 3, subtract the number','Multiply by 5, add 30, divide by 5, subtract the number','Add 7, multiply by 2, subtract 14, divide by 2, subtract the number'],['0','6','5','4'],[3,4,2,1],['In the first three the result is the number added, divided by the multiplier: $\\frac{10}{2} = 5$, $\\frac{12}{3} = 4$ and $\\frac{30}{5} = 6$.','In the last, $\\frac{2(n + 7) - 14}{2} - n = 0$.'],1).replace('Match List I with List II.','Each trick in List I starts from a number you think of. Match it with its result.'),
];

banks['p2ch07-area']=[
p(1,S,'A rectangular garden is 15 m by 6 m. A square garden has the same perimeter. Which garden has the larger area?',['the square, by $20.25 \\text{ m}^2$','the rectangle, by $20.25 \\text{ m}^2$','neither: the areas are equal','the square, by $11.25 \\text{ m}^2$'],['The perimeter is $2(15 + 6) = 42$ m, so the square has side 10.5 m.','The square has area $110.25 \\text{ m}^2$ and the rectangle $90 \\text{ m}^2$: $110.25 - 90 = 20.25$.'],'(a) the square, by $20.25 \\text{ m}^2$'),
p(2,S,'A floor 4.5 m by 3.6 m is covered with square tiles of side 30 cm. How many tiles are needed?',['162','180','18','1620'],['Along the length $450 \\div 30 = 15$ tiles fit, and across $360 \\div 30 = 12$.','$15 \\times 12 = 180$ tiles.'],'(b) 180'),
p(3,S,'A right-angled triangle has sides 9 cm, 12 cm and 15 cm. What is the perpendicular from the right angle to the longest side?',['54 cm','6 cm','7.2 cm','7.5 cm'],['The area is $\\frac{1}{2} \\times 9 \\times 12 = 54 \\text{ cm}^2$.','Taking the 15 cm side as base: $\\frac{1}{2} \\times 15 \\times h = 54$, so $h = 7.2$ cm.'],'(c) 7.2 cm'),
p(4,S,'A parallelogram has area $84 \\text{ cm}^2$ and sides 7 cm and 14 cm. What is its height on the 14 cm side?',['12 cm','7 cm','14 cm','6 cm'],['Area $=$ base $\\times$ height: $14 \\times h = 84$.','$h = 6$ cm.'],'(d) 6 cm'),
p(5,S,'A rhombus has sides 25 cm and one diagonal 48 cm. What is its area?',['$336 \\text{ cm}^2$','$600 \\text{ cm}^2$','$1200 \\text{ cm}^2$','$672 \\text{ cm}^2$'],['The diagonals bisect each other at right angles: half the other diagonal is $\\sqrt{25^2 - 24^2} = 7$, so it is 14 cm.','Area $= \\frac{1}{2} \\times 48 \\times 14 = 336 \\text{ cm}^2$.'],'(a) $336 \\text{ cm}^2$'),
p(6,S,'A field shaped like a trapezium has area $91 \\text{ m}^2$ and parallel sides 16 m and 10 m. How far apart are the parallel sides?',['3.5 m','7 m','14 m','5.7 m'],['Area $= \\frac{1}{2} \\times (16 + 10) \\times h = 13h$.','$13h = 91$, so $h = 7$ m.'],'(b) 7 m'),
p(7,M,'$ABCD$ is a parallelogram of area $50 \\text{ cm}^2$, and $P$ is any point on side $CD$. Which statements are correct?',['Triangle $APB$ has area $25 \\text{ cm}^2$.','$APB$ has the same area for every $P$.','$APD$ and $BPC$ together make $25 \\text{ cm}^2$.','Triangle $APB$ has area $50 \\text{ cm}^2$.'],['$APB$ has base $AB$ and the parallelogram\'s height, so it is half of it wherever $P$ is; the other two make the rest.'],'(a), (b), (c)'),
p(8,M,'A kite has diagonals 14 cm and 10 cm. Which statements are correct?',['Its area is $70 \\text{ cm}^2$.','A 20 cm by 3.5 cm rectangle has equal area.','It equals a 14 cm by 10 cm rectangle.','Its area is $140 \\text{ cm}^2$.'],['Area $= \\frac{1}{2} \\times 14 \\times 10 = 70 = 20 \\times 3.5$, half the rectangle round the kite.'],'(a), (b)'),
p(9,M,'On a map, 1 cm stands for 2 km. Which statements are correct?',['$1 \\text{ m}^2 = 10\\,000 \\text{ cm}^2$','$7.5 \\text{ m}^2 = 75\\,000 \\text{ cm}^2$','$1 \\text{ km}^2 = 1000 \\text{ m}^2$','$1 \\text{ cm}^2$ of map is $4 \\text{ km}^2$.'],['An area unit is a length unit squared: $100^2 = 10\\,000$, $2^2 = 4$, but $1000^2 = 10^6$, not 1000.'],'(a), (b), (d)'),
p(10,M,'A trapezium has parallel sides 14 cm and 10 cm, 6 cm apart. Which statements are correct?',['Its area is $72 \\text{ cm}^2$.','Triangle: base 24 cm, height 6 cm, equal area.','Rectangle: 12 cm by 6 cm, equal area.','Its area is $144 \\text{ cm}^2$.'],['Area $= \\frac{1}{2} \\times (14 + 10) \\times 6 = 72$, and $\\frac{1}{2} \\times 24 \\times 6 = 12 \\times 6 = 72$.'],'(a), (b), (c)'),
p(11,N,'On a map, 1 cm stands for 2 km. A lake covers $6 \\text{ cm}^2$ of the map. What is its real area, in $\\text{km}^2$?',[],['$1 \\text{ cm}^2$ on the map stands for $2 \\times 2 = 4 \\text{ km}^2$.','$6 \\times 4 = 24 \\text{ km}^2$.'],'24'),
p(12,N,'A rectangular farm plot is 330 ft by 264 ft. An acre is $43\\,560 \\text{ ft}^2$. How many acres is the plot?',[],['Area $= 330 \\times 264 = 87\\,120 \\text{ ft}^2$.','$87\\,120 \\div 43\\,560 = 2$ acres.'],'2'),
p(13,N,'A garden is a pentagon: a rectangle 14 m by 9 m with a triangle on top, whose base is one 14 m side and whose height is 6 m. Find its area, in $\\text{m}^2$.',[],['Rectangle: $14 \\times 9 = 126 \\text{ m}^2$. Triangle: $\\frac{1}{2} \\times 14 \\times 6 = 42 \\text{ m}^2$.','$126 + 42 = 168 \\text{ m}^2$.'],'168'),
m(14,['Parallelogram, base 25, height 14','Rhombus, diagonals 14 and 48','Trapezium, parallel sides 16 and 10, height 7','Triangle, base 6, height 5'],['91','15','350','336'],[3,4,1,2],['$25 \\times 14 = 350$ and $\\frac{1}{2} \\times 14 \\times 48 = 336$.','$\\frac{1}{2} \\times 26 \\times 7 = 91$ and $\\frac{1}{2} \\times 6 \\times 5 = 15$.'],0).replace('Match List I with List II.','All lengths are in cm. Match each figure with its area, in square centimetres.'),
m(15,['$1 \\text{ m}^2$, in $\\text{cm}^2$','$1 \\text{ ft}^2$, in $\\text{in}^2$','$1 \\text{ km}^2$, in $\\text{m}^2$','$1 \\text{ cm}^2$, in $\\text{mm}^2$'],['100','1 000 000','10 000','144'],[3,4,2,1],['1 m is 100 cm and 1 ft is 12 in, so $100^2 = 10\\,000$ and $12^2 = 144$.','1 km is 1000 m and 1 cm is 10 mm: $1000^2 = 1\\,000\\,000$ and $10^2 = 100$.'],3),
];

